(() => {
 const attr = key => idleon.engine.getGameAttribute(key);
 const version = idleon.getGameVersion();
 const names = attr("GetPlayersUsernames");
 const currentName = attr("UserInfo")[0];
 const targetPlayerId = names.indexOf(currentName);
 if (targetPlayerId !== __TARGET_PLAYER__) throw new Error("Prayer replay target mismatch");
 const database = attr("PlayerDATABASE").h;
 const levels = attr("PrayersUnlocked");
 const definitions = attr("CustomLists").h.PrayerInfo;
 const prepared = attr("DNSM").h;
 const bits = {};
 for (const id of [9,39,53]) {
  bits[id] = Number(idleon.callFunction("GamingStatType","SuperBitType",id,0));
  if (!Number.isFinite(bits[id])) throw new Error("Missing native Superbit "+id);
 }
 const passiveActive = bits[9] === 1 || bits[39] === 1;
 const passiveFraction = 0.2 * bits[9] + (0.2 * bits[39] + 0.2 * bits[53]);
 const ordinaryBonuses = {}, prayerInputs = {};
 for (const id of [7,5,16]) {
  if (!definitions[id] || levels[id] === undefined) throw new Error("Missing initialized Prayer "+id);
  const base = Number(definitions[id][3]), level = Number(levels[id]);
  if (!Number.isFinite(base) || !Number.isFinite(level)) throw new Error("Non-finite Prayer input "+id);
  const levelMultiplier = Math.max(1,1+(level-1)/10);
  prayerInputs[id] = {base,level,levelMultiplier};
  ordinaryBonuses[id] = Math.round(base * levelMultiplier);
 }
 const players = names.map((name,playerId) => {
  if (!database[name]) throw new Error("Missing native character record "+name);
  const rawSlots = database[name].h.Prayers;
  if (rawSlots !== undefined && !Array.isArray(rawSlots)) throw new Error("Unexpected native Prayer slots "+name);
  const slotCount = rawSlots === undefined ? 0 : rawSlots.length;
  // Fresh source predicate: an empty raw list never reaches the final empty-slot match.
  const noEquippedPrayers = slotCount > 0 && rawSlots.every(slot => slot == -1);
  const bonuses = {};
  for (const id of [7,5,16]) {
   const input = prayerInputs[id];
   if (!passiveActive || !noEquippedPrayers) {
    bonuses[id] = rawSlots !== undefined && rawSlots.indexOf(id) !== -1 ? ordinaryBonuses[id] : 0;
   } else {
    bonuses[id] = id !== 5 && input.level > 0.5
     ? Math.round(passiveFraction * input.base * input.levelMultiplier) : 0;
   }
  }
  return {playerId,playerName:name,rawSlots:rawSlots === undefined ? null : rawSlots,slotCount,noEquippedPrayers,bonuses};
 });
 return {
  context:{version,targetPlayerId,targetPlayerName:currentName},bits,passiveActive,passiveFraction,
  prayerInputs,ordinaryBonuses,players,
  cachedNoEquippedDiagnostic:Object.prototype.hasOwnProperty.call(prepared,"PrayNonEq") ? prepared.PrayNonEq : null
 };
})()
